#!/bin/bash
set -euo pipefail

if [ "$#" -ne 1 ]; then
  printf 'Usage: %s LOGFILE\n' "$0" >&2
  exit 2
fi

logfile=$1

if [ ! -r "$logfile" ]; then
  printf 'Error: cannot read file: %s\n' "$logfile" >&2
  exit 1
fi

awk '
  NF == 0 { next }
  $2 == "ERROR" {
    if (match($0, /\[[^]]*\]/)) {
      component = substr($0, RSTART + 1, RLENGTH - 2)
      errors[component]++
    }
  }
  END {
    for (component in errors) {
      printf "%d\t%s\n", errors[component], component
    }
  }
' < "$logfile" | LC_ALL=C sort -t $'\t' -k1,1nr -k2 | awk '
  BEGIN { FS = "\t" }
  { printf "%s %s\n", $1, $2 }
'
